"""Build source-bound browser, Markdown and LaTeX research editions from achieved records."""
import argparse
import hashlib
import html
import json
from pathlib import Path
import subprocess

REPO='https://github.com/MontrealAI/AGI-Alpha-Invention-Flywheel-Lab'

def money(x):return f'${x/1_000_000:,.6f}'
def esc(s):
    for a,b in [('\\',r'\textbackslash{}'),('&',r'\&'),('%',r'\%'),('$',r'\$'),('#',r'\#'),('_',r'\_'),('{',r'\{'),('}',r'\}')]:s=str(s).replace(a,b)
    return s

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--run',required=True);parser.add_argument('--output',required=True);args=parser.parse_args();run=Path(args.run).resolve();out=Path(args.output).resolve();out.mkdir(parents=True,exist_ok=True)
    report=json.loads((run/'REPORT.json').read_text());frozen=json.loads((run/'FROZEN.json').read_text());audit=json.loads((run/'PACKAGE_AUDIT.json').read_text())
    if not audit['accepted'] or audit['source_sha256']!=report['source_sha256']:raise ValueError('ACCEPTED_SOURCE_BOUND_AUDIT_REQUIRED')
    representative=report['representative'];r=json.loads((run/'worlds'/f"{representative['seed']}-{representative['case']}-{representative['arm']}"/'RESULT.json').read_text());g=json.loads((run/'worlds'/f"{representative['seed']}-{representative['case']}-{representative['arm']}"/'GROWTH.json').read_text());s=r['summary']
    rows=report['frontier']['regions'];pairs=report['comparisons']['pairs'];central_pairs=[p for p in pairs if p['identity'][1]=='central'];delta=[p['profit_delta_microUSD'] for p in central_pairs]
    title='AGI ALPHA: A Recoverable Enterprise That Finances Productive Expansion'
    findings=f"The registered design completed {report['worlds']} separate simulated enterprises. In the central growth region, {report['central']['commercial_successes']}/{report['central']['runs']} met the predeclared commercial criteria. Independent checks reexecuted useful artifacts and replayed native financial records and operating semantics. These finite authored trajectories are not calibrated probabilities of real market success."
    representative_text=f"The first registered central growth enterprise collected {money(s['collections'])} from {r['paid_jobs']} settled complete deliveries to {r['customers']} paying customers, including {r['repeat_customers']} repeat customers. Complete modeled expenses were {money(s['expenses'])}; profit and available earned funds were {money(s['profit'])} and {money(s['unrestrictedEarned'])}. {r['profitable_earned_continuations']} profitable deliveries used prior unrestricted earnings. Initial seed capital was {money(r['config']['opening'])}; terminal seed-backed protection was {money(s['equityProtectionBacking'])}."
    contrast=f"Under matched starting capital and contracts, central growth minus baseline profit ranged from {money(min(delta))} to {money(max(delta))}, with mean {money(sum(delta)/len(delta))}. This is the value of the added commercial options and resulting behavior, not proof that a more elaborate algorithm is superior."
    mechanics='Voluntary budget-feasible qualified order precedes production. The admitted service executor produces the actual artifact; a separate checker verifies source-bound complete outcomes before native prepare. Hour-clock clearing follows acceptance. Paid acquisition and capacity contracts are bought only from current unrestricted earnings using an audited state-bound reservation and resolved prepaid resource obligations. Expiring channels expose finite prospects with overlap, fatigue, failed access and renewal costs; exposure is never an order. Customers retain human, rival and refusal alternatives even when the enterprise lacks capacity.'
    recovery='Every monetary command is recorded as an exact signed write-ahead intent before native mutation. Operating state, event queue and prepared decision are separately sealed against the retained local simulation key and a native tape prefix. Crash tests cover startup, qualified order, production, acceptance and clearing/tax acknowledgment loss. Public exports omit private keys and cannot reopen accounts; they support independent audit and fresh reproduction. Storage protection is limited to the supported operator-owned local POSIX filesystem.'
    costs='All amounts are simulated microUSD. Complete modeled costs include development/search/qualification/setup, acquisition including unsuccessful and unused exposure, onboarding, production, supplier, verification/support, correction envelopes, maintenance, payment fees and conditional tax. Exact pinned runtime dependencies and local CPU are checked or recorded separately. Host and model billing are unavailable and remain explicit envelopes or unknown; no zero-billing inference is made. Human complete-work hours and fully loaded wage proxies are authored commercial references. No actual paid frontier-model inference, live customers, outreach, financial transactions or deployment occurred.'
    scale='Exact aggregation of native records reconciles overlapping collected-delivery prefixes and all expense/cash flows. This validates accounting aggregation, not a forward buyer or production model. USD1M,10M,100M,1B and10B trailing-365-day targets remain unreached in this finite native experiment. The separate PR22 months22-23 and PR23 months27-29 hypothetical billion-dollar projections use different capital, offers, channel contracts, allocation policies, outreach costs and reserve semantics. They remain UNBRIDGED_NATIVE_SCALE; neither number is selected as the native enterprise forecast.'
    limits='The operating implementation, conditional commercial result and growth result are separate outcomes. Small synthetic complete services and authored buyer/channel/supplier behavior do not establish empirical market demand or autonomous invention superiority. The frozen source inventory, finite audience and permanent native refund tails remain real edition constraints. Follow-on construction must earn or explicitly seed its own resources; no balance is copied between evaluation businesses.'
    next_text=report['next_action']
    sections=[('Achieved result',findings),('Representative enterprise',representative_text),('Matched growth consequence',contrast),('Connected operating path',mechanics),('Recovery and independent verification',recovery),('Cost and inference limits',costs),('Scale and unmet milestones',scale),('Boundaries and next action',limits+' '+next_text)]
    if frozen['protocol']['edition']=='connected014-confirmation-002':
        sections.insert(1,('Preserved failure and new intervention','Edition001 preserved15result files and14accepted operating audits, then stopped when a paid reactivation response was logged before its source exposure. No full001protocol verdict is claimed. Edition002 repairs that trace order, retires every exposed001seed, registers a fresh service cohort and customer-event seeds, and compares retained growth with a public competitive-price option. The option costs5USD once and0.05USD per quoted decision, including declined offers. Both arms use neutral keyed indifference for equal-utility choices. No missing receipt or original outcome was fabricated or relabeled.'))
    table_headers=['Region','Arm','Businesses','Settled deliveries','Modeled profit range','Covered']
    table_rows=[[x['case'],x['arm'],str(x['businesses']),f"{x['collected_delivery_range'][0]}-{x['collected_delivery_range'][1]}",f"{money(x['profit_range_microUSD'][0])} to {money(x['profit_range_microUSD'][1])}",f"{x['covered_businesses']}/{x['businesses']}"] for x in rows]
    financial=[('Recognized revenue',s['revenue']),('Collected payments',s['collections']),('Incurred complete modeled costs',s['expenses']),('Paid costs',s['expensePaid']),('Profit',s['profit']),('Cash',s['cash']),('Receivables',r['owned_account']['ledger']['receivables']),('Unpaid liabilities',s['payables']),('Native tail reserves',s['tailReserve']),('Custody reserves',s['custodyReserve']),('Working reserve',s['workingCapital']),('Unrestricted earned funds',s['unrestrictedEarned']),('Seed capital',r['config']['opening']),('Seed-backed protection',s['equityProtectionBacking'])]
    md=[f'# {title}','',f"Frozen source: `{report['source_sha256']}`",f"Published source commit: `{frozen['git_commit']}`",'',f"Operating: **{report['outcomes']['operating_implementation']}**",f"Commercial: **{report['outcomes']['commercial_result']}**",f"Growth: **{report['outcomes']['growth_result']}**",f"Native billion-scale: **{report['outcomes']['billion_native_scale']}**",'']
    for heading,text in sections:md.extend([f'## {heading}','',text,''])
    md.extend(['## All registered economic regions','', '| '+' | '.join(table_headers)+' |','| '+' | '.join(['---']*len(table_headers))+' |'])
    md.extend('| '+' | '.join(row)+' |' for row in table_rows);md.extend(['','## Representative financial state','','| Measure | Simulated USD |','| --- | ---: |']);md.extend(f'| {name} | {money(value)} |' for name,value in financial)
    md.extend(['','## Reproduce','', '```sh','python -m pip install -r requirements-commercial010.txt','python -m connected_enterprise run --output /absolute/new/connected014','python -m connected_enterprise audit --output /absolute/new/connected014','python -m connected_enterprise resume --output /absolute/new/connected014','```','',f'[Repository]({REPO}) | [Canonical PR22]({REPO}/pull/22) | [PR23 hypothesis]({REPO}/pull/23)',''])
    (out/'REPORT.md').write_text('\n'.join(md))
    table='<table><thead><tr>'+''.join(f'<th>{html.escape(x)}</th>' for x in table_headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{html.escape(x)}</td>' for x in row)+'</tr>' for row in table_rows)+'</tbody></table>'
    ftable='<table>'+''.join(f'<tr><th>{html.escape(k)}</th><td>{money(v)}</td></tr>' for k,v in financial)+'</table>'
    body=''.join(f'<section><h2>{html.escape(h)}</h2><p>{html.escape(t)}</p></section>' for h,t in sections)
    page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><style>body{{font:17px/1.6 system-ui;color:#172c43;background:#f4f7fa;margin:0}}main{{max-width:1080px;margin:auto;padding:54px 30px}}h1{{font-size:38px;line-height:1.15;max-width:850px}}h2{{font-size:23px;margin-top:35px}}.eyebrow{{color:#17675b;font-weight:700;letter-spacing:.12em}}.key{{padding:22px;background:white;border-left:5px solid #17675b;box-shadow:0 3px 20px #1231}}code{{overflow-wrap:anywhere}}table{{border-collapse:collapse;width:100%;background:white;font-size:14px;margin:20px 0}}td,th{{padding:11px;text-align:left;border-bottom:1px solid #d7e1ea}}footer{{font-size:13px;overflow-wrap:anywhere}}a{{color:#006c7c}}@media(max-width:700px){{main{{padding:25px 15px}}h1{{font-size:30px}}table{{display:block;overflow-x:auto}}}}</style><main><div class="eyebrow">AGI ALPHA / CONNECTED 014 / CONDITIONAL SIMULATION</div><h1>{title}</h1><div class="key">{html.escape(findings)}</div>{body}<h2>All registered economic regions</h2>{table}<h2>Representative financial state</h2>{ftable}<h2>Reproduce</h2><p>Use <a href="OPERATOR.md">the operator procedure</a>, the published source and the key-free evidence package. Historical results and failed regions remain separate.</p><footer>Frozen source SHA256: <code>{report['source_sha256']}</code><br>Committed source: <code>{frozen['git_commit']}</code><br><a href="{REPO}">Repository</a> · <a href="{REPO}/pull/22">Canonical evidence</a> · <a href="{REPO}/pull/23">Separate distribution hypothesis</a></footer></main></html>'''
    (out/'index.html').write_text(page)
    tex=[r'\documentclass[10pt,letterpaper]{article}',r'\usepackage[margin=0.82in]{geometry}',r'\usepackage[T1]{fontenc}',r'\usepackage{lmodern}',r'\usepackage{booktabs,longtable,array,xcolor,hyperref}',r'\hypersetup{colorlinks=true,urlcolor=teal,linkcolor=teal}',r'\setlength{\parindent}{0pt}\setlength{\parskip}{6pt}',r'\title{'+esc(title)+'}',r'\author{Montreal.AI / AGI ALPHA engineering campaign}',r'\date{30 October 2026}',r'\begin{document}\maketitle',r'\begin{abstract}'+esc(findings)+r'\end{abstract}']
    tex.extend([r'\textbf{Source SHA256:} \texttt{'+report['source_sha256'][:32]+r'}\\\texttt{'+report['source_sha256'][32:]+'}',r'\textbf{Committed source:} \texttt{'+str(frozen['git_commit'])+'}'])
    for heading,text in sections:tex.extend([r'\section{'+esc(heading)+'}',esc(text)])
    tex.extend([r'\section{All registered economic regions}',r'\small\begin{longtable}{@{}p{2.55cm}p{1.1cm}r r p{4.1cm}r@{}}',r'\toprule Region & Arm & N & Paid & Modeled profit range & Covered \\ \midrule\endhead'])
    tex.extend(' & '.join(esc(x) for x in row)+r' \\' for row in table_rows);tex.extend([r'\bottomrule\end{longtable}\normalsize',r'\section{Representative financial state}',r'\begin{longtable}{@{}lr@{}}\toprule Measure & Simulated USD \\ \midrule\endhead'])
    tex.extend(esc(k)+' & '+esc(money(v))+r' \\' for k,v in financial);tex.extend([r'\bottomrule\end{longtable}',r'\section{Source and reproduction}',r'\url{'+REPO+'}',r'\par Read the operator procedure and preserve the registered source, source/configuration manifest, all native financial tapes, accepted artifacts, independent audit receipts and every non-reaching or failed trajectory. The browser edition and Markdown report are generated from the same achieved records.',r'\end{document}'])
    (out/'PAPER.tex').write_text('\n'.join(tex)+'\n')
    for _ in range(2):subprocess.run(['pdflatex','-interaction=nonstopmode','-halt-on-error','-output-directory',str(out),str(out/'PAPER.tex')],check=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT)
    files={name:hashlib.sha256((out/name).read_bytes()).hexdigest() for name in ['REPORT.md','index.html','PAPER.tex','PAPER.pdf']}
    (out/'PUBLICATION.json').write_text(json.dumps({'schema':'agi-alpha/connected014-research-edition/v1','source_sha256':report['source_sha256'],'source_commit':frozen['git_commit'],'report_sha256':hashlib.sha256((run/'REPORT.json').read_bytes()).hexdigest(),'audit_sha256':hashlib.sha256((run/'PACKAGE_AUDIT.json').read_bytes()).hexdigest(),'files':files,'rendering':'REQUIRES_VISUAL_INSPECTION_BEFORE_DELIVERY'},indent=2)+'\n')
    print(json.dumps({'files':files,'source_sha256':report['source_sha256']}))

if __name__=='__main__':main()
